    rs=[1,8,15,22]
    cs=[1,8,15,22]
    centers=[[grid[r+2][c+2] for c in cs] for r in rs]
    # Exceptional interior colors propagate across the gutters between matching tiles.
    for i,r in enumerate(rs):
        for j,c in enumerate(cs):
            color=centers[i][j]
            if color in (0,2,4):
                continue
            for k in range(4):
                if k != j and centers[i][k] == color:
                    lo,hi=sorted((cs[j],cs[k]))
                    for y in range(r+1,r+4):
                        for x in range(lo+5,hi):
                            if grid[y][x] == 0:
                                g[y][x]=color
                if k != i and centers[k][j] == color:
                    lo,hi=sorted((rs[i],rs[k]))
                    for x in range(c+1,c+4):
                        for y in range(lo+5,hi):
                            if grid[y][x] == 0:
                                g[y][x]=color
    return g
